export function resolveSkinVisualMotifs(skin: {
  id: string;
  icon_pack?: string[];
  composer_charm_uri?: string | null;
}): BuiltinSkinIconEntry {
  const builtin = BUILTIN_SKIN_ICONS[skin.id];
  return {
    motifLabel: builtin?.motifLabel || '自定义图标与器物信物',
    iconPack:
      skin.icon_pack && skin.icon_pack.length > 0
        ? skin.icon_pack
        : builtin?.iconPack || [],
    composerCharmUri: skin.composer_charm_uri || builtin?.composerCharmUri || null,
  };
}
